/**
 * Provides the application-owned shadcn Dialog primitives generated by its CLI.
 * Radix owns modal focus, keyboard dismissal, and accessible title/description
 * associations; these wrappers supply theme styles and optional close controls.
 * Callers own dialog state, meaningful labels, and application actions.
 */
"use client"

import * as React from "react"
import { cn } from "@/lib/utils"
import { Dialog as DialogPrimitive } from "radix-ui"

import { Button } from "@/components/ui/button"
import { XIcon } from "lucide-react"

const dialogClasses = {
  overlay: "fixed inset-0 isolate z-50 bg-black/10 duration-100 supports-backdrop-filter:backdrop-blur-xs data-open:animate-in data-open:fade-in-0 data-closed:animate-out data-closed:fade-out-0",
  content: "fixed top-1/2 left-1/2 z-50 grid w-full max-w-[calc(100%-2rem)] -translate-x-1/2 -translate-y-1/2 gap-4 rounded-xl bg-popover p-4 text-sm text-popover-foreground ring-1 ring-foreground/10 duration-100 outline-none sm:max-w-sm data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95",
  header: "flex flex-col gap-2",
  footer: "-mx-4 -mb-4 flex flex-col-reverse gap-2 rounded-b-xl border-t bg-muted/50 p-4 sm:flex-row sm:justify-end",
  title: "font-heading text-base leading-none font-medium",
  description: "text-sm text-muted-foreground *:[a]:underline *:[a]:underline-offset-3 *:[a]:hover:text-foreground",
  close: "absolute top-2 right-2",
  accessibleLabel: "sr-only",
};

/**
 * Owns controlled or uncontrolled modal visibility through Radix.
 * @param props - Underlying element attributes and wrapper presentation options.
 * @returns The composed dialog element.
 */
function Dialog({
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Root>) {
  return <DialogPrimitive.Root data-slot="dialog" {...props} />
}

/**
 * Renders the control that opens its enclosing dialog.
 * @param props - Underlying element attributes and wrapper presentation options.
 * @returns The composed dialog element.
 */
function DialogTrigger({
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Trigger>) {
  return <DialogPrimitive.Trigger data-slot="dialog-trigger" {...props} />
}

/**
 * Mounts dialog elements outside the surrounding layout.
 * @param props - Underlying element attributes and wrapper presentation options.
 * @returns The composed dialog element.
 */
function DialogPortal({
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Portal>) {
  return <DialogPrimitive.Portal data-slot="dialog-portal" {...props} />
}

/**
 * Renders a control that closes its enclosing dialog.
 * @param props - Underlying element attributes and wrapper presentation options.
 * @returns The composed dialog element.
 */
function DialogClose({
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Close>) {
  return <DialogPrimitive.Close data-slot="dialog-close" {...props} />
}

/**
 * Renders the themed backdrop for a modal dialog.
 * @param props - Underlying element attributes and wrapper presentation options.
 * @returns The composed dialog element.
 */
function DialogOverlay({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Overlay>) {
  return (
    <DialogPrimitive.Overlay
      data-slot="dialog-overlay"
      className={cn(
        dialogClasses.overlay,
        className
      )}
      {...props}
    />
  )
}

/**
 * Renders portaled modal content with an optional accessible close control.
 * @param props - Underlying element attributes and wrapper presentation options.
 * @returns The composed dialog element.
 */
function DialogContent({
  className,
  children,
  showCloseButton = true,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Content> & {
  showCloseButton?: boolean
}) {
  return (
    <DialogPortal>
      <DialogOverlay />
      <DialogPrimitive.Content
        data-slot="dialog-content"
        className={cn(
          dialogClasses.content,
          className
        )}
        {...props}
      >
        {children}
        {showCloseButton && (
          <DialogPrimitive.Close data-slot="dialog-close" asChild>
            <Button
              variant="ghost"
              className={dialogClasses.close}
              size="icon-sm"
            >
              <XIcon
              />
              <span className={dialogClasses.accessibleLabel}>Close</span>
            </Button>
          </DialogPrimitive.Close>
        )}
      </DialogPrimitive.Content>
    </DialogPortal>
  )
}

/**
 * Groups the title and description within dialog content.
 * @param props - Underlying element attributes and wrapper presentation options.
 * @returns The composed dialog element.
 */
function DialogHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="dialog-header"
      className={cn(dialogClasses.header, className)}
      {...props}
    />
  )
}

/**
 * Groups dialog actions with an optional close button.
 * @param props - Underlying element attributes and wrapper presentation options.
 * @returns The composed dialog element.
 */
function DialogFooter({
  className,
  showCloseButton = false,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  showCloseButton?: boolean
}) {
  return (
    <div
      data-slot="dialog-footer"
      className={cn(
        dialogClasses.footer,
        className
      )}
      {...props}
    >
      {children}
      {showCloseButton && (
        <DialogPrimitive.Close asChild>
          <Button variant="outline">Close</Button>
        </DialogPrimitive.Close>
      )}
    </div>
  )
}

/**
 * Provides the accessible title associated with the dialog.
 * @param props - Underlying element attributes and wrapper presentation options.
 * @returns The composed dialog element.
 */
function DialogTitle({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Title>) {
  return (
    <DialogPrimitive.Title
      data-slot="dialog-title"
      className={cn(
        dialogClasses.title,
        className
      )}
      {...props}
    />
  )
}

/**
 * Provides supporting text associated with the dialog.
 * @param props - Underlying element attributes and wrapper presentation options.
 * @returns The composed dialog element.
 */
function DialogDescription({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Description>) {
  return (
    <DialogPrimitive.Description
      data-slot="dialog-description"
      className={cn(
        dialogClasses.description,
        className
      )}
      {...props}
    />
  )
}

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
  DialogTrigger,
}
